// ARCH-001.a | 2026-11-10 | One typed registry holds every content definition of a session.
// Decision: .agents/architecture/ARCH-001.a-content-registry.md
// Journal: .agents/days/2026-11-12.md
using System;
using System.Collections.Generic;
using System.Text;

namespace TomorrowAtEight.Content
{
    /// <summary>Where a registered result comes from; decides who owns its lifetime.</summary>
    public enum ContentSource
    {
        /// <summary>Plain immutable C# definition (recipes, data). Nothing to release.</summary>
        Definition,
        /// <summary>Unity object generated by code. Owned and destroyed by the session.</summary>
        Procedural,
        /// <summary>Asset referenced by the generated ImportedAssetCatalog. Borrowed.</summary>
        Imported,
        /// <summary>Resource shipped with the Unity player. Borrowed third-party dependency.</summary>
        BuiltIn,
    }

    public sealed class ContentException : Exception
    {
        public ContentException(string message) : base(message) { }
        public ContentException(string message, Exception inner) : base(message, inner) { }
    }

    /// <summary>Lookup used by imported entries; implemented by ImportedAssetCatalog.</summary>
    public interface IImportedAssetSource
    {
        bool TryGetAsset(string contentId, out UnityEngine.Object asset);
    }

    public sealed class ContentEntry
    {
        public string Id { get; internal set; }
        public string Kind { get; internal set; }
        public Type ResultType { get; internal set; }
        public ContentSource Source { get; internal set; }
        /// <summary>Identifies the implementation reviewed by ARCH-001.c metadata.</summary>
        public string ProviderRevision { get; internal set; }
        public IReadOnlyList<string> Dependencies { get; internal set; }
        public bool IsResolved { get; internal set; }

        internal Func<ContentRegistry, object> Provider;
        internal object Value;
    }

    /// <summary>
    /// Registration, validation, and lazy shared resolution of content.
    /// Main thread only. One instance per content session.
    /// </summary>
    public sealed class ContentRegistry : IDisposable
    {
        readonly Dictionary<string, ContentEntry> m_Entries = new Dictionary<string, ContentEntry>(StringComparer.Ordinal);
        readonly List<ContentEntry> m_Order = new List<ContentEntry>();
        readonly List<string> m_RegistrationErrors = new List<string>();
        readonly List<ContentEntry> m_ResolveStack = new List<ContentEntry>();
        readonly List<UnityEngine.Object> m_OwnedObjects = new List<UnityEngine.Object>();
        readonly IImportedAssetSource m_Imported;
        readonly Action<UnityEngine.Object> m_DestroyOwned;
        bool m_Sealed;
        bool m_Disposed;

        /// <param name="imported">Optional generated catalog for imported entries.</param>
        /// <param name="destroyOwned">Releases generated Unity objects at shutdown.</param>
        public ContentRegistry(IImportedAssetSource imported, Action<UnityEngine.Object> destroyOwned)
        {
            m_Imported = imported;
            m_DestroyOwned = destroyOwned;
        }

        public bool IsSealed => m_Sealed;
        public IReadOnlyList<ContentEntry> Entries => m_Order;
        public int OwnedObjectCount => m_OwnedObjects.Count;

        public int ResolvedCount
        {
            get
            {
                int count = 0;
                for (int i = 0; i < m_Order.Count; i++)
                    if (m_Order[i].IsResolved)
                        count++;
                return count;
            }
        }

        /// <summary>
        /// Declares one content definition. Problems are collected and reported together
        /// by <see cref="ValidateAndSeal"/>; registration order never selects an override.
        /// </summary>
        public void Register<T>(
            ContentKey<T> key,
            ContentSource source,
            string providerRevision,
            Func<ContentRegistry, T> provider,
            params IContentKey[] dependencies)
        {
            if (m_Sealed)
                throw new InvalidOperationException($"Cannot register '{key}': the registry is sealed.");

            if (key.Id == null)
            {
                m_RegistrationErrors.Add("A registration used an unset content key (default struct value).");
                return;
            }
            if (provider == null)
            {
                m_RegistrationErrors.Add($"'{key.Id}' was registered without a provider.");
                return;
            }
            if (string.IsNullOrEmpty(providerRevision))
                m_RegistrationErrors.Add($"'{key.Id}' was registered without a provider revision.");

            // Keys built through ContentKey<T> are already checked; this also covers
            // registrations that reach the registry through an untyped path later.
            string keyError = ContentKeyRules.Check(key.Id, typeof(T));
            if (keyError != null)
            {
                m_RegistrationErrors.Add(keyError);
                return;
            }

            if (m_Entries.TryGetValue(key.Id, out ContentEntry existing))
            {
                m_RegistrationErrors.Add(
                    $"Duplicate content key '{key.Id}' (already registered as {existing.ResultType.Name}, " +
                    $"registered again as {typeof(T).Name}).");
                return;
            }

            var dependencyIds = new List<string>(dependencies == null ? 0 : dependencies.Length);
            if (dependencies != null)
            {
                for (int i = 0; i < dependencies.Length; i++)
                {
                    string id = dependencies[i]?.Id;
                    if (id == null)
                        m_RegistrationErrors.Add($"'{key.Id}' declares an unset dependency key at index {i}.");
                    else if (!dependencyIds.Contains(id))
                        dependencyIds.Add(id);
                }
            }

            var entry = new ContentEntry
            {
                Id = key.Id,
                Kind = ContentKeyRules.KindOf(key.Id),
                ResultType = typeof(T),
                Source = source,
                ProviderRevision = providerRevision,
                Dependencies = dependencyIds,
                Provider = registry => provider(registry),
            };
            m_Entries.Add(entry.Id, entry);
            m_Order.Add(entry);
        }

        /// <summary>Declares an entry served by the generated imported asset catalog.</summary>
        public void RegisterImported<T>(ContentKey<T> key, string providerRevision, params IContentKey[] dependencies)
            where T : UnityEngine.Object
        {
            string id = key.Id;
            Register(key, ContentSource.Imported, providerRevision, registry =>
            {
                if (registry.m_Imported != null &&
                    registry.m_Imported.TryGetAsset(id, out UnityEngine.Object asset) &&
                    asset is T typed)
                {
                    return typed;
                }
                throw new ContentException(
                    $"Imported asset for '{id}' is missing or is not a {typeof(T).Name}. " +
                    "Run TomorrowAtEight/Run/Rebuild Imported Asset Catalog in the Unity Editor.");
            }, dependencies);
        }

        /// <summary>
        /// Checks duplicates, type contracts, unknown dependencies, cycles, and imported
        /// references, then freezes the registry. Throws one exception listing every problem.
        /// </summary>
        public void ValidateAndSeal()
        {
            if (m_Sealed)
                return;

            var errors = new List<string>(m_RegistrationErrors);

            for (int i = 0; i < m_Order.Count; i++)
            {
                ContentEntry entry = m_Order[i];
                for (int d = 0; d < entry.Dependencies.Count; d++)
                {
                    string dependency = entry.Dependencies[d];
                    if (!m_Entries.ContainsKey(dependency))
                        errors.Add($"Unknown dependency: {entry.Id} -> {dependency} (not registered).");
                }

                if (entry.Source == ContentSource.Imported)
                {
                    if (m_Imported == null)
                    {
                        errors.Add($"'{entry.Id}' is declared as imported but no ImportedAssetCatalog was loaded.");
                    }
                    else if (!m_Imported.TryGetAsset(entry.Id, out UnityEngine.Object asset) || asset == null)
                    {
                        errors.Add($"'{entry.Id}' is declared as imported but the catalog has no reference for it.");
                    }
                    else if (!entry.ResultType.IsInstanceOfType(asset))
                    {
                        errors.Add($"'{entry.Id}' expects {entry.ResultType.Name} but the catalog references a {asset.GetType().Name}.");
                    }
                }
            }

            FindCycles(errors);

            if (errors.Count > 0)
            {
                var message = new StringBuilder();
                message.Append("Content validation failed with ").Append(errors.Count).Append(" problem(s):");
                for (int i = 0; i < errors.Count; i++)
                    message.Append("\n  - ").Append(errors[i]);
                throw new ContentException(message.ToString());
            }

            m_Sealed = true;
        }

        void FindCycles(List<string> errors)
        {
            // 0 = unvisited, 1 = on the current path, 2 = finished.
            var state = new Dictionary<string, int>(StringComparer.Ordinal);
            var path = new List<string>();
            for (int i = 0; i < m_Order.Count; i++)
                Visit(m_Order[i].Id, state, path, errors);
        }

        void Visit(string id, Dictionary<string, int> state, List<string> path, List<string> errors)
        {
            if (!m_Entries.TryGetValue(id, out ContentEntry entry))
                return;
            state.TryGetValue(id, out int visitState);
            if (visitState == 2)
                return;
            if (visitState == 1)
            {
                int start = path.IndexOf(id);
                var chain = new StringBuilder();
                for (int i = start; i < path.Count; i++)
                    chain.Append(path[i]).Append(" -> ");
                chain.Append(id);
                errors.Add($"Dependency cycle: {chain}.");
                return;
            }

            state[id] = 1;
            path.Add(id);
            for (int d = 0; d < entry.Dependencies.Count; d++)
                Visit(entry.Dependencies[d], state, path, errors);
            path.RemoveAt(path.Count - 1);
            state[id] = 2;
        }

        public bool TryGetEntry(string id, out ContentEntry entry)
        {
            if (id == null)
            {
                entry = null;
                return false;
            }
            return m_Entries.TryGetValue(id, out entry);
        }

        public bool Contains(IContentKey key) => key?.Id != null && m_Entries.ContainsKey(key.Id);

        /// <summary>
        /// Returns the single shared result for the key in this session, creating it on first use.
        /// Resolving an entity or scene recipe returns its definition; nothing is spawned.
        /// </summary>
        public T Resolve<T>(ContentKey<T> key)
        {
            if (m_Disposed)
                throw new ObjectDisposedException(nameof(ContentRegistry));
            if (!m_Sealed)
                throw new InvalidOperationException($"Cannot resolve '{key}' before ValidateAndSeal succeeds.");
            if (key.Id == null || !m_Entries.TryGetValue(key.Id, out ContentEntry entry))
                throw new ContentException($"Unknown content key '{key}'{DescribeResolveChain()}.");
            if (entry.ResultType != typeof(T))
            {
                throw new ContentException(
                    $"Content key '{key.Id}' is registered as {entry.ResultType.Name} but was requested as " +
                    $"{typeof(T).Name}{DescribeResolveChain()}.");
            }

            if (m_ResolveStack.Count > 0)
            {
                ContentEntry parent = m_ResolveStack[m_ResolveStack.Count - 1];
                if (!Contains(parent.Dependencies, entry.Id))
                {
                    // Undeclared edges would hide parts from rights validation (ARCH-001.c).
                    throw new ContentException(
                        $"'{parent.Id}' resolved '{entry.Id}' without declaring it as a dependency.");
                }
            }

            if (entry.IsResolved)
                return (T)entry.Value;

            if (m_ResolveStack.Contains(entry))
                throw new ContentException($"Dependency cycle while resolving '{entry.Id}'{DescribeResolveChain()}.");

            m_ResolveStack.Add(entry);
            object value;
            try
            {
                value = entry.Provider(this);
            }
            catch (ContentException)
            {
                throw;
            }
            catch (Exception exception)
            {
                throw new ContentException(
                    $"Provider for '{entry.Id}' failed{DescribeResolveChain()}: {exception.Message}", exception);
            }
            finally
            {
                m_ResolveStack.RemoveAt(m_ResolveStack.Count - 1);
            }

            bool missing = value == null || (value is UnityEngine.Object unityObject && unityObject == null);
            if (missing)
                throw new ContentException($"Provider for '{entry.Id}' returned no result{DescribeResolveChain()}.");

            entry.Value = value;
            entry.IsResolved = true;
            if (entry.Source == ContentSource.Procedural && value is UnityEngine.Object owned)
                m_OwnedObjects.Add(owned);
            return (T)value;
        }

        /// <summary>Ordered dependency closure of the given root keys, roots included.</summary>
        public List<string> GetDependencyClosure(IEnumerable<string> rootIds)
        {
            var result = new List<string>();
            var seen = new HashSet<string>(StringComparer.Ordinal);
            var pending = new Stack<string>();
            foreach (string root in rootIds)
                pending.Push(root);

            while (pending.Count > 0)
            {
                string id = pending.Pop();
                if (id == null || !seen.Add(id))
                    continue;
                result.Add(id);
                if (m_Entries.TryGetValue(id, out ContentEntry entry))
                {
                    for (int d = entry.Dependencies.Count - 1; d >= 0; d--)
                        pending.Push(entry.Dependencies[d]);
                }
            }
            return result;
        }

        /// <summary>
        /// Releases generated Unity objects in reverse creation order. Call after entity
        /// views and world-local prefabs are gone. Imported and built-in assets are borrowed.
        /// </summary>
        public void Dispose()
        {
            if (m_Disposed)
                return;
            m_Disposed = true;

            for (int i = m_OwnedObjects.Count - 1; i >= 0; i--)
            {
                UnityEngine.Object owned = m_OwnedObjects[i];
                if (owned != null && m_DestroyOwned != null)
                    m_DestroyOwned(owned);
            }
            m_OwnedObjects.Clear();

            for (int i = 0; i < m_Order.Count; i++)
            {
                m_Order[i].Value = null;
                m_Order[i].IsResolved = false;
            }
        }

        static bool Contains(IReadOnlyList<string> list, string value)
        {
            for (int i = 0; i < list.Count; i++)
                if (string.Equals(list[i], value, StringComparison.Ordinal))
                    return true;
            return false;
        }

        string DescribeResolveChain()
        {
            if (m_ResolveStack.Count == 0)
                return string.Empty;
            var chain = new StringBuilder(" (while resolving ");
            for (int i = 0; i < m_ResolveStack.Count; i++)
            {
                if (i > 0)
                    chain.Append(" -> ");
                chain.Append(m_ResolveStack[i].Id);
            }
            chain.Append(')');
            return chain.ToString();
        }
    }
}
